<?php
declare(strict_types=1);
chdir(__DIR__ . '/..');
require_once __DIR__ . '/../php/session_security.php';
AppSessionStart();
require_once __DIR__ . '/../php/db_connection.php';
require_once __DIR__ . '/../php/admin_auth_helper.php';
require_once __DIR__ . '/../php/complaints_incidents_helper.php';
require_once __DIR__ . '/../php/activity_logger.php';
AdminRequireLogin();
ensureComplaintsIncidentsTable($pdo);
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');

function ce(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function cj(int $code, bool $ok, string $message): never { http_response_code($code); header('Content-Type: application/json'); echo json_encode(['success'=>$ok,'message'=>$message]); exit; }
function categoryLabel(string $v): string { return ['tour-service'=>'Tour or guide service','accommodation'=>'Hotel or accommodation','transportation'=>'Boat or transportation','safety-security'=>'Safety or security','environmental'=>'Environmental concern','staff-conduct'=>'Staff or operator conduct','payment-booking'=>'Payment or booking','other'=>'Other concern'][$v] ?? ucwords(str_replace('-',' ',$v)); }
function evidenceList(?string $json, int $reportId): array { $list=json_decode((string)$json,true);if(!is_array($list))return[];$urls=[];foreach(array_values($list)as$i=>$v){if(is_string($v)&&(preg_match('#^uploads/complaints/[A-Za-z0-9_.-]+$#D',$v)||preg_match('/^private:[A-Za-z0-9_.-]+$/D',$v)))$urls[]='php/complaint_evidence.php?report_id='.$reportId.'&file='.$i;}return$urls; }
if (empty($_SESSION['admin_complaint_csrf'])) $_SESSION['admin_complaint_csrf']=bin2hex(random_bytes(32));
$csrf=(string)$_SESSION['admin_complaint_csrf']; $adminId=(int)$_SESSION['admin_id']; $adminName=(string)($_SESSION['admin_name']??$_SESSION['username']??'Administrator');

if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (!hash_equals($csrf,(string)($_POST['csrf_token']??''))) cj(403,false,'Your security token expired. Refresh and try again.');
  $id=(int)($_POST['case_id']??0); $status=strtolower(trim((string)($_POST['status']??''))); $priority=strtolower(trim((string)($_POST['priority']??''))); $assignee=(int)($_POST['assigned_admin_id']??0); $note=trim((string)($_POST['note']??'')); $resolution=trim((string)($_POST['resolution_summary']??''));
  if ($id<1 || !in_array($status,['submitted','in_review','resolved','dismissed'],true) || !in_array($priority,['low','normal','high','urgent'],true)) cj(422,false,'Select a valid status and priority.');
  if (in_array($status,['resolved','dismissed'],true) && mb_strlen($resolution)<10) cj(422,false,'Add a clear final outcome of at least 10 characters.');
  if (mb_strlen($note)>3000 || mb_strlen($resolution)>5000) cj(422,false,'The case note is too long.');
  $pdo->beginTransaction();
  try {
    $q=$pdo->prepare('SELECT * FROM complaints_incidents WHERE complaint_incident_id=? FOR UPDATE'); $q->execute([$id]); $old=$q->fetch(PDO::FETCH_ASSOC); if(!$old) throw new RuntimeException('Case not found.');
    if($assignee){$q=$pdo->prepare('SELECT COUNT(*) FROM admin_users WHERE admin_id=?');$q->execute([$assignee]);if(!(int)$q->fetchColumn())throw new RuntimeException('Selected administrator is unavailable.');}
    $reviewed=$status!=='submitted'?'COALESCE(first_reviewed_at,NOW())':'first_reviewed_at'; $resolved=in_array($status,['resolved','dismissed'],true)?'NOW()':'NULL';
    $q=$pdo->prepare("UPDATE complaints_incidents SET status=?,priority=?,assigned_admin_id=?,first_reviewed_at={$reviewed},resolved_at={$resolved},resolution_summary=? WHERE complaint_incident_id=?"); $q->execute([$status,$priority,$assignee?:null,$resolution?:null,$id]);
    $changed=$status!==$old['status']||$priority!==($old['priority']??'normal')||$assignee!==(int)($old['assigned_admin_id']??0);
    if($changed||$note!==''||$resolution!==''){$kind=$status!==$old['status']?'status_change':($note!==''?'note':'case_update');$q=$pdo->prepare('INSERT INTO complaint_incident_updates(complaint_incident_id,admin_id,action_type,from_status,to_status,note)VALUES(?,?,?,?,?,?)');$q->execute([$id,$adminId,$kind,$old['status'],$status,$note?:($resolution?:'Case details updated.')]);}
    logActivity($pdo,'Admin',$adminId,$adminName,'Complaint Case Updated','Updated report '.$old['reference_number'].' to '.str_replace('_',' ',$status).'.','Complaints & Incidents',$id);
    $pdo->commit(); cj(200,true,'Case updated successfully.');
  } catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());cj(500,false,$e instanceof RuntimeException?$e->getMessage():'The case could not be updated.');}
}

$search=trim((string)($_GET['search']??'')); $sf=strtolower((string)($_GET['status']??'')); $pf=strtolower((string)($_GET['priority']??'')); $tf=strtolower((string)($_GET['type']??'')); $af=strtolower((string)($_GET['assignment']??'')); $sort=strtolower((string)($_GET['sort']??'newest')); $page=max(1,(int)($_GET['page']??1)); $per=12; $where=[];$params=[];
if($search!==''){$where[]='(c.reference_number LIKE :q OR c.subject LIKE :q OR c.location LIKE :q OR t.full_name LIKE :q OR t.email LIKE :q)';$params[':q']='%'.$search.'%';}
if(in_array($sf,['submitted','in_review','resolved','dismissed'],true)){$where[]='c.status=:status';$params[':status']=$sf;}else$sf='';
if(in_array($pf,['low','normal','high','urgent'],true)){$where[]='c.priority=:priority';$params[':priority']=$pf;}else$pf='';
if(in_array($tf,['complaint','incident'],true)){$where[]='c.report_type=:type';$params[':type']=$tf;}else$tf='';
if($af==='mine'){$where[]='c.assigned_admin_id=:aid';$params[':aid']=$adminId;}elseif($af==='unassigned')$where[]='c.assigned_admin_id IS NULL';else$af='';
$ws=$where?' WHERE '.implode(' AND ',$where):''; $order=match($sort){'oldest'=>'c.submitted_at ASC','priority'=>"FIELD(c.priority,'urgent','high','normal','low'),c.submitted_at ASC",'updated'=>'c.updated_at DESC',default=>'c.submitted_at DESC'};
$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='submitted') submitted,SUM(status='in_review') in_review,SUM(status IN('submitted','in_review') AND priority IN('high','urgent')) priority_open,SUM(status='resolved') resolved FROM complaints_incidents")->fetch(PDO::FETCH_ASSOC)?:[];
$q=$pdo->prepare('SELECT COUNT(*) FROM complaints_incidents c LEFT JOIN tourist t ON t.tourist_id=c.tourist_id'.$ws);$q->execute($params);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;
$q=$pdo->prepare("SELECT c.*,t.full_name tourist_name,t.email tourist_email,t.phone_number tourist_phone,t.address tourist_address,a.full_name assigned_name,a.username assigned_username FROM complaints_incidents c LEFT JOIN tourist t ON t.tourist_id=c.tourist_id LEFT JOIN admin_users a ON a.admin_id=c.assigned_admin_id {$ws} ORDER BY {$order} LIMIT {$per} OFFSET {$offset}");$q->execute($params);$cases=$q->fetchAll(PDO::FETCH_ASSOC);
$admins=$pdo->query("SELECT admin_id,COALESCE(NULLIF(full_name,''),username) display_name FROM admin_users ORDER BY display_name")->fetchAll(PDO::FETCH_ASSOC);$ids=array_map(fn($v)=>(int)$v['complaint_incident_id'],$cases);$hist=[];
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT u.*,COALESCE(NULLIF(a.full_name,''),a.username,'Administrator') admin_name FROM complaint_incident_updates u LEFT JOIN admin_users a ON a.admin_id=u.admin_id WHERE u.complaint_incident_id IN({$marks}) ORDER BY u.created_at DESC,u.update_id DESC");$q->execute($ids);foreach($q->fetchAll(PDO::FETCH_ASSOC)as$u)$hist[(int)$u['complaint_incident_id']][]=$u;}
foreach($cases as &$c){$c['evidence']=evidenceList($c['evidence_paths']??null,(int)$c['complaint_incident_id']);$c['updates']=$hist[(int)$c['complaint_incident_id']]??[];$c['category_label']=categoryLabel((string)$c['category']);}unset($c);
function pageUrl(int $p):string{$x=$_GET;unset($x['export']);$x['page']=$p;return'adcomplaintsincidents.php?'.http_build_query($x);}
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment;filename="complaint-cases-'.date('Y-m-d').'.csv"');$o=fopen('php://output','wb');fputcsv($o,['Reference','Type','Subject','Tourist','Category','Priority','Status','Assigned','Submitted']);foreach($cases as$c)fputcsv($o,[$c['reference_number'],$c['report_type'],$c['subject'],$c['tourist_name'],$c['category_label'],$c['priority'],$c['status'],$c['assigned_name']?:'Unassigned',$c['submitted_at']]);fclose($o);exit;}
$hasFilters=$search!==''||$sf!==''||$pf!==''||$tf!==''||$af!=='';
?>
