<section class="ci-process"><div class="ci-process-title"><strong>Handling workflow</strong><span>A consistent path for every report</span></div><?php foreach([['Triage','Verify & prioritize'],['Assign','Set case owner'],['Investigate','Document actions'],['Resolve','Record outcome']]as$i=>$s):?><div class="ci-step"><b><?=$i+1?></b><div><strong><?=$s[0]?></strong><span><?=$s[1]?></span></div></div><?php endforeach;?></section>
<section class="ci-panel"><form class="ci-toolbar" method="get"><div class="ci-field ci-search"><label>Search cases</label><input name="search" value="<?=ce($search)?>" placeholder="Reference, subject, tourist or location"></div>
<?php $filters=[['status','Status',[''=>'All statuses','submitted'=>'Submitted','in_review'=>'In review','resolved'=>'Resolved','dismissed'=>'Dismissed'],$sf],['priority','Priority',[''=>'All priorities','urgent'=>'Urgent','high'=>'High','normal'=>'Normal','low'=>'Low'],$pf],['type','Report type',[''=>'All types','complaint'=>'Complaint','incident'=>'Incident'],$tf],['assignment','Assignment',[''=>'All cases','mine'=>'Assigned to me','unassigned'=>'Unassigned'],$af],['sort','Sort by',['newest'=>'Newest first','oldest'=>'Oldest first','priority'=>'Priority first','updated'=>'Recently updated'],$sort]];foreach($filters as[$name,$title,$opts,$selected]):?><div class="ci-field"><label><?=$title?></label><select name="<?=$name?>"><?php foreach($opts as$v=>$label):?><option value="<?=ce($v)?>" <?=$selected===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><?php endforeach;?><div class="ci-actions"><button class="ci-btn primary">Apply</button><a class="ci-btn" href="adcomplaintsincidents.php">Reset</a><a class="ci-btn" href="<?=ce(pageUrl($page).'&export=csv')?>">CSV</a></div></form>
<?php if(!$cases):?><div class="ci-empty"><svg viewBox="0 0 24 24"><path d="M6 3h9l4 4v14H6zM14 3v5h5M9 13h7"></path></svg><h3><?=$hasFilters?'No matching reports':'No reports submitted yet'?></h3><p><?=$hasFilters?'Adjust or clear the current filters.':'New tourist reports will appear here.'?></p></div><?php else:?><div class="ci-table-wrap"><table class="ci-table"><thead><tr><th>Case</th><th>Report</th><th>Tourist</th><th>Category</th><th>Priority</th><th>Status</th><th>Assigned to</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($cases as$c):?><tr><td><span class="ci-ref"><?=ce($c['reference_number'])?></span></td><td class="ci-subject"><strong><?=ce($c['subject'])?></strong><span><?=ucfirst(ce($c['report_type']))?> · <?=ce($c['location'])?></span></td><td class="ci-person"><strong><?=ce($c['tourist_name']?:'Tourist #'.$c['tourist_id'])?></strong><span><?=ce($c['tourist_email'])?></span></td><td><?=ce($c['category_label'])?></td><td><span class="ci-pill <?=ce($c['priority'])?>"><?=ce($c['priority'])?></span></td><td><span class="ci-pill <?=ce($c['status'])?>"><?=ce(str_replace('_',' ',$c['status']))?></span></td><td><span class="<?=empty($c['assigned_admin_id'])?'unassigned':''?>"><?=ce($c['assigned_name']?:$c['assigned_username']?:'Unassigned')?></span></td><td><?=date('M j, Y',strtotime($c['submitted_at']))?><br><small><?=date('g:i A',strtotime($c['submitted_at']))?></small></td><td><button class="ci-btn ci-view" type="button" data-case="<?=ce(json_encode($c,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>">Review</button></td></tr><?php endforeach;?></tbody></table></div><footer class="ci-footer"><span>Showing <?=$offset+1?>–<?=min($offset+$per,$total)?> of <?=number_format($total)?> cases</span><nav class="ci-pages"><a class="ci-page <?=$page<=1?'disabled':''?>" href="<?=ce(pageUrl(max(1,$page-1)))?>">‹</a><?php for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++):?><a class="ci-page <?=$p===$page?'active':''?>" href="<?=ce(pageUrl($p))?>"><?=$p?></a><?php endfor;?><a class="ci-page <?=$page>=$pages?'disabled':''?>" href="<?=ce(pageUrl(min($pages,$page+1)))?>">›</a></nav></footer><?php endif;?></section></div></main></div>
<div class="ci-drawer" id="drawer" hidden><section class="ci-drawer-panel" role="dialog" aria-modal="true"><header class="ci-drawer-head"><div class="ci-drawer-title"><span class="ci-icon">!</span><div><h2>Review case</h2><p id="dRef"></p></div></div><button class="ci-close" type="button">×</button></header><div class="ci-drawer-body"><div class="ci-case-scroll"><div class="ci-card"><h3>Report overview</h3><div class="ci-overview" id="dOverview"></div></div><div class="ci-card"><h3>What happened</h3><div class="ci-description" id="dDescription"></div></div><div class="ci-card" id="peopleCard"><h3>People involved</h3><div class="ci-description" id="dPeople"></div></div><div class="ci-card" id="actionCard"><h3>Immediate action reported</h3><div class="ci-description" id="dAction"></div></div><div class="ci-card" id="evidenceCard"><h3>Photo evidence</h3><div class="ci-evidence" id="dEvidence"></div></div><div class="ci-card"><h3>Tourist contact</h3><div class="ci-overview" id="dTourist"></div></div><div class="ci-card"><h3>Case activity</h3><div class="ci-timeline" id="dTimeline"></div></div></div><aside class="ci-side"><form class="ci-form" id="caseForm"><input type="hidden" name="csrf_token" value="<?=ce($csrf)?>"><input type="hidden" name="case_id" id="caseId"><h3 style="margin:0 0 13px">Case handling</h3><label><span>Status</span><select name="status" id="caseStatus"><option value="submitted">Submitted — awaiting triage</option><option value="in_review">In review — investigation active</option><option value="resolved">Resolved — outcome completed</option><option value="dismissed">Dismissed — no further action</option></select></label><label><span>Priority</span><select name="priority" id="casePriority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label><span>Assigned administrator</span><select name="assigned_admin_id" id="caseAssignee"><option value="0">Unassigned</option><?php foreach($admins as$a):?><option value="<?=(int)$a['admin_id']?>"><?=ce($a['display_name'])?><?=(int)$a['admin_id']===$adminId?' (Me)':''?></option><?php endforeach;?></select></label><label><span>Internal case note</span><textarea name="note" placeholder="Document verification, calls, findings, or the next action..."></textarea></label><label><span>Resolution / dismissal summary</span><textarea name="resolution_summary" id="caseResolution" placeholder="Required when resolving or dismissing..."></textarea></label><p class="ci-help">The tourist can see the status. Keep notes factual and record a clear final outcome before closing.</p><button class="ci-btn primary ci-save" type="submit">Save case update</button></form></aside></div></section></div><div class="ci-toast" id="toast" hidden></div>
<script>(()=>{const drawer=document.getElementById('drawer'),form=document.getElementById('caseForm'),toast=document.getElementById('toast');const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const label=v=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());const date=v=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'}):'Not recorded';const box=(n,v)=>`<div class="ci-data"><small>${esc(n)}</small><strong>${esc(v||'Not provided')}</strong></div>`;function notify(m,e=false){toast.textContent=m;toast.classList.toggle('error',e);toast.hidden=false;setTimeout(()=>toast.hidden=true,3000)}function open(c){drawer.hidden=false;document.body.style.overflow='hidden';dRef.textContent=c.reference_number+' · '+label(c.report_type);caseId.value=c.complaint_incident_id;caseStatus.value=c.status;casePriority.value=c.priority||'normal';caseAssignee.value=c.assigned_admin_id||'0';caseResolution.value=c.resolution_summary||'';dOverview.innerHTML=box('Subject',c.subject)+box('Category',c.category_label)+box('Event date',date(c.incident_at))+box('Location',c.location)+box('Submitted',date(c.submitted_at))+box('Preferred contact',label(c.preferred_contact));dDescription.textContent=c.description||'No description.';[[peopleCard,dPeople,c.people_involved],[actionCard,dAction,c.immediate_action]].forEach(([card,target,v])=>{card.hidden=!v;target.textContent=v||''});evidenceCard.hidden=!c.evidence?.length;dEvidence.innerHTML=(c.evidence||[]).map(p=>`<a href="../${esc(p)}" target="_blank"><img src="../${esc(p)}" alt="Report evidence"></a>`).join('');dTourist.innerHTML=box('Name',c.tourist_name||'Tourist #'+c.tourist_id)+box('Email',c.tourist_email)+box('Phone',c.tourist_phone)+box('Address',c.tourist_address);const events=[...(c.updates||[]),{action_type:'submitted',admin_name:'Tourist',created_at:c.submitted_at,note:'Report submitted for review.'}];dTimeline.innerHTML=events.map(v=>`<div class="ci-event"><strong>${esc(label(v.action_type))}</strong><span>${esc(v.admin_name||'System')} · ${esc(date(v.created_at))}</span>${v.note?`<p>${esc(v.note)}</p>`:''}</div>`).join('')}document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{try{open(JSON.parse(b.dataset.case))}catch(e){notify('Unable to open case.',true)}});function close(){drawer.hidden=true;document.body.style.overflow=''}document.querySelector('.ci-close').onclick=close;drawer.onclick=e=>{if(e.target===drawer)close()};document.onkeydown=e=>{if(e.key==='Escape')close()};form.onsubmit=async e=>{e.preventDefault();if(['resolved','dismissed'].includes(caseStatus.value)&&caseResolution.value.trim().length<10){caseResolution.focus();return notify('Add a clear final outcome before closing.',true)}const b=form.querySelector('button[type=submit]');b.disabled=true;b.textContent='Saving...';try{const r=await fetch('adcomplaintsincidents.php',{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}),j=await r.json();if(!r.ok||!j.success)throw Error(j.message);notify(j.message);setTimeout(()=>location.reload(),600)}catch(x){notify(x.message||'Update failed.',true);b.disabled=false;b.textContent='Save case update'}}})();</script></body></html>
